class Solution {
public:
    ListNode* mergeNodes(ListNode* head) {
        ListNode* modify = head->next;
        ListNode* curr = head->next;
        int sum = 0;
        while (curr) {
            if (curr->val != 0) {
                sum += curr->val;
            } else {
                modify->val = sum;
                modify->next = curr->next;
                if (curr->next) {
                    modify = curr->next;
                }
                sum = 0;
            }
            curr = curr->next;
        }
        return head->next;
    }
};
